// function clamp(val, min, max) mein teen numbers do
// Agar koi bhi non-number: null
// Val < min: min, Val > max: max, Baaki: val

solution:
function clamp(val, min, max) {
  if (typeof val !== "number" || typeof min !== "number" || typeof max !== "number") return null
  if (val < min) return min
  if (val > max) return max
  return val
}
